export async function testProxyPool(proxies:string[],probe:(proxy:string)=>Promise<{ok:boolean;latencyMs?:number}>,progress:(done:number,total:number)=>void=()=>{}){
 const pool=[...new Set(proxies.map(value=>value.trim()).filter(Boolean))];
 if(!pool.length||pool.length>8)throw Error('Enter between 1 and 8 proxy URLs');
 const results:Array<{index:number;ok:boolean;latencyMs:number|null}>=[];let next=0,done=0;
 async function worker(){while(next<pool.length){const index=next++;let result;
  try{const response=await probe(pool[index]!);result={index,ok:response.ok===true,latencyMs:Number.isFinite(response.latencyMs)?response.latencyMs!:null};}
  catch{result={index,ok:false,latencyMs:null};}
  results[index]=result;progress(++done,pool.length);
 }}
 await Promise.all(Array.from({length:Math.min(2,pool.length)},()=>worker()));return results;
}

